package convert

// CalcTargetDimensions computes (width, height) for ASCII art given flags.
// Parameters:
//   imgW, imgH: image dimensions in pixels
//   termW, termH: terminal dimensions in characters (or 0 if unknown)
//   width, height: user-provided dimensions (-W, -H); 0 if unset
//   dims: user-provided dimensions slice ([w, h]); length 0 if unset
//   full: --full flag
// Returns target (w, h) in characters.
// charAspect: for ASCII the terminal char aspect ratio factor is 2
// (chars roughly 2× taller than wide).
func CalcTargetDimensions(imgW, imgH, termW, termH, width, height int, dims []int, full bool) (int, int) {
	if len(dims) == 2 {
		return dims[0], dims[1]
	}
	if full {
		w := termW - 1
		h := int(float64(w) * float64(imgH) / float64(imgW) / 2.0)
		return w, h
	}
	if width > 0 {
		h := int(float64(width) * float64(imgH) / float64(imgW) / 2.0)
		return width, h
	}
	if height > 0 {
		w := int(float64(height) * float64(imgW) / float64(imgH) * 2.0)
		return w, height
	}
	// default: use terminal height - 1
	h := termH - 1
	w := int(float64(h) * float64(imgW) / float64(imgH) * 2.0)
	if w > termW-1 {
		w = termW - 1
		h = int(float64(w) * float64(imgH) / float64(imgW) / 2.0)
	}
	return w, h
}
EOF
