package convert

import (
	"fmt"
	"os"
	"strings"
)

// ColorMode is how colors are emitted.
type ColorMode int

const (
	ColorNone ColorMode = iota
	Color256
	ColorTrue
)

// DetectColorMode returns the color mode based on TERM/COLORTERM env vars.
func DetectColorMode() ColorMode {
	term := os.Getenv("TERM")
	colorterm := strings.ToLower(os.Getenv("COLORTERM"))
	if term == "" || term == "dumb" {
		return ColorNone
	}
	if colorterm == "truecolor" || colorterm == "24bit" {
		return ColorTrue
	}
	if strings.Contains(term, "256") || strings.Contains(term, "direct") || strings.Contains(term, "truecolor") {
		if colorterm == "truecolor" || colorterm == "24bit" || strings.Contains(term, "direct") || strings.Contains(term, "truecolor") {
			return ColorTrue
		}
		return Color256
	}
	// xterm, screen etc. usually support 256 colors
	if strings.Contains(term, "xterm") || strings.Contains(term, "screen") || strings.Contains(term, "vt100") || strings.Contains(term, "tmux") || strings.Contains(term, "linux") || strings.Contains(term, "rxvt") || strings.Contains(term, "ansi") || strings.Contains(term, "cygwin") || strings.Contains(term, "konsole") {
		return Color256
	}
	return ColorNone
}

// Ansi24 returns an ANSI 24-bit color escape for (r,g,b) foreground applied to s.
func Ansi24(r, g, b uint8, s string) string {
	return fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", r, g, b, s)
}

// Ansi24Bg returns an ANSI 24-bit color escape for (r,g,b) background applied to s.
func Ansi24Bg(r, g, b uint8, s string) string {
	return fmt.Sprintf("\x1b[48;2;%d;%d;%dm%s\x1b[0m", r, g, b, s)
}

// Ansi8 returns an ANSI 256-color escape applied to s.
func Ansi8(code int, s string) string {
	return fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", code, s)
}

// Ansi8Bg returns an ANSI 256-color escape applied to s (background).
func Ansi8Bg(code int, s string) string {
	return fmt.Sprintf("\x1b[48;5;%dm%s\x1b[0m", code, s)
}

// RGBTo256 converts an RGB triple to a 256-color palette index matching the
// original tool's behavior. For a neutral gray the extreme cube corners are
// replaced by codes 0 (black) and 15 (white).
func RGBTo256(r, g, b uint8) int {
	// 6x6x6 cube uses levels {0, 95, 135, 175, 215, 255}.
	levels := [6]int{0, 95, 135, 175, 215, 255}
	cubeIdx := func(v uint8) int {
		// choose nearest of levels.
		best := 0
		bestD := 1000
		vv := int(v)
		for i, l := range levels {
			d := vv - l
			if d < 0 {
				d = -d
			}
			if d < bestD {
				bestD = d
				best = i
			}
		}
		return best
	}
	ri := cubeIdx(r)
	gi := cubeIdx(g)
	bi := cubeIdx(b)
	if ri == gi && gi == bi {
		// use basic black/white for extremes
		if ri == 0 {
			return 0
		}
		if ri == 5 {
			return 15
		}
	}
	return 16 + 36*ri + 6*gi + bi
}

// GrayscaleTo256 maps a grayscale value to a 256-color palette index for the
// grayscale flag output.
func GrayscaleTo256(v uint8) int {
	return RGBTo256(v, v, v)
}
