package convert

import (
	"image"
	"strings"
)

// Luminance returns the Rec 601 luminance (Y) of an RGB8 pixel, matching Go's
// color.GrayModel which uses Y = (19595*R + 38470*G + 7471*B + 1<<15) >> 16.
func Luminance(r, g, b uint8) uint8 {
	return uint8((19595*uint32(r) + 38470*uint32(g) + 7471*uint32(b) + (1 << 15)) >> 16)
}

// mapIndex computes the index into charMap for a brightness value 0..255.
func mapIndex(bright uint8, mapLen int) int {
	idx := int(bright) * mapLen / 255
	if idx >= mapLen {
		idx = mapLen - 1
	}
	if idx < 0 {
		idx = 0
	}
	return idx
}

// AsciiOptions controls the ASCII output.
type AsciiOptions struct {
	Map          string // character ramp, darkest -> lightest
	Color        bool   // ANSI color
	Grayscale    bool   // grayscale output
	Negative     bool   // negative colors
	ColorBg      bool   // paint background instead of foreground
	ColorMode    ColorMode
	FontColor    [3]uint8 // used when --font-color is set (else white)
	FontColorSet bool
}

// ConvertToAscii converts an RGBA image to ASCII character rows.
// Each row is a string containing the line (with optional ANSI codes).
func ConvertToAscii(img *image.RGBA, opts AsciiOptions) []string {
	chars := []rune(opts.Map)
	if len(chars) == 0 {
		chars = []rune(DefaultAsciiMap)
	}
	n := len(chars)
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	rows := make([]string, h)
	for y := 0; y < h; y++ {
		var sb strings.Builder
		for x := 0; x < w; x++ {
			i := y*img.Stride + x*4
			r := img.Pix[i+0]
			g := img.Pix[i+1]
			bc := img.Pix[i+2]
			lum := Luminance(r, g, bc)
			idx := mapIndex(lum, n)
			if opts.Negative {
				idx = n - 1 - idx
			}
			ch := string(chars[idx])
			// Determine the color to apply, if any.
			if opts.Color {
				cr, cg, cbl := r, g, bc
				if opts.Negative {
					cr = 255 - cr
					cg = 255 - cg
					cbl = 255 - cbl
				}
				if opts.ColorMode == ColorTrue {
					if opts.ColorBg {
						ch = Ansi24Bg(cr, cg, cbl, ch)
					} else {
						ch = Ansi24(cr, cg, cbl, ch)
					}
				} else {
					code := RGBTo256(cr, cg, cbl)
					if opts.ColorBg {
						ch = Ansi8Bg(code, ch)
					} else {
						ch = Ansi8(code, ch)
					}
				}
			} else if opts.Grayscale {
				gr := lum
				if opts.Negative {
					gr = 255 - gr
				}
				if opts.ColorMode == ColorTrue {
					if opts.ColorBg {
						ch = Ansi24Bg(gr, gr, gr, ch)
					} else {
						ch = Ansi24(gr, gr, gr, ch)
					}
				} else {
					code := GrayscaleTo256(gr)
					if opts.ColorBg {
						ch = Ansi8Bg(code, ch)
					} else {
						ch = Ansi8(code, ch)
					}
				}
			} else if opts.FontColorSet {
				cr, cg, cbl := opts.FontColor[0], opts.FontColor[1], opts.FontColor[2]
				if opts.ColorMode == ColorTrue {
					ch = Ansi24(cr, cg, cbl, ch)
				} else {
					code := RGBTo256(cr, cg, cbl)
					ch = Ansi8(code, ch)
				}
			}
			sb.WriteString(ch)
		}
		rows[y] = sb.String()
	}
	return rows
}

// FlipImageX flips the image horizontally in-place (returns a new one).
func FlipImageX(src *image.RGBA) *image.RGBA {
	b := src.Bounds()
	w, h := b.Dx(), b.Dy()
	dst := image.NewRGBA(b)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			si := y*src.Stride + x*4
			di := y*dst.Stride + (w-1-x)*4
			copy(dst.Pix[di:di+4], src.Pix[si:si+4])
		}
	}
	return dst
}

func FlipImageY(src *image.RGBA) *image.RGBA {
