// ConvertToBraille converts an already-resized RGBA image to braille rows.
// Each braille character represents a 2x4 block of pixels.
//
// Input image dimensions must be (2*cols) by (4*rows).
// If dither is true, Floyd-Steinberg dithering is applied on the luminance.
// Otherwise, pixels with brightness >= threshold are "on".
func ConvertToBraille(img *image.RGBA, cols, rows, threshold int, dither bool, opts AsciiOptions) []string {
	// braille dot bit positions:
	//   col0  col1
	//   bit0  bit3   (row 0)
	//   bit1  bit4   (row 1)
	//   bit2  bit5   (row 2)
	//   bit6  bit7   (row 3)
	dotBits := [4][2]int{
		{1, 8},
		{2, 16},
		{4, 32},
		{64, 128},
	}
	b := img.Bounds()
	iw, ih := b.Dx(), b.Dy()
	lum := make([]float64, iw*ih)
	for y := 0; y < ih; y++ {
		for x := 0; x < iw; x++ {
			i := y*img.Stride + x*4
			lum[y*iw+x] = float64(Luminance(img.Pix[i], img.Pix[i+1], img.Pix[i+2]))
		}
	}
	on := make([]bool, iw*ih)
	if dither {
		// Floyd-Steinberg
		for y := 0; y < ih; y++ {
			for x := 0; x < iw; x++ {
				old := lum[y*iw+x]
				var newv float64
				if old >= 128 {
					newv = 255
					on[y*iw+x] = true
				} else {
					newv = 0
				}
				err := old - newv
				// distribute
				if x+1 < iw {
					lum[y*iw+x+1] += err * 7 / 16
				}
				if y+1 < ih {
					if x > 0 {
						lum[(y+1)*iw+x-1] += err * 3 / 16
					}
					lum[(y+1)*iw+x] += err * 5 / 16
					if x+1 < iw {
						lum[(y+1)*iw+x+1] += err * 1 / 16
					}
				}
			}
		}
	} else {
		t := float64(threshold)
		for i, v := range lum {
			if v >= t {
				on[i] = true
			}
		}
	}

	result := make([]string, rows)
	for cy := 0; cy < rows; cy++ {
		var sb strings.Builder
		for cx := 0; cx < cols; cx++ {
			var dots int
			// average color of the 2x4 block
			var rSum, gSum, bSum, aSum int
			cnt := 0
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := cx*2 + dx
					py := cy*4 + dy
					if px >= iw || py >= ih {
						continue
					}
					if opts.Negative {
						if !on[py*iw+px] {
							dots |= dotBits[dy][dx]
						}
					} else {
						if on[py*iw+px] {
							dots |= dotBits[dy][dx]
						}
					}
					idx := py*img.Stride + px*4
					rSum += int(img.Pix[idx+0])
					gSum += int(img.Pix[idx+1])
					bSum += int(img.Pix[idx+2])
					aSum += int(img.Pix[idx+3])
					cnt++
				}
			}
			r := rune(0x2800 + dots)
			ch := string(r)
			if cnt > 0 {
				avgR := uint8(rSum / cnt)
				avgG := uint8(gSum / cnt)
				avgB := uint8(bSum / cnt)
				if opts.Color {
					cr, cg, cbl := avgR, avgG, avgB
					if opts.Negative {
						cr = 255 - cr
						cg = 255 - cg
						cbl = 255 - cbl
					}
					if opts.ColorMode == ColorTrue {
						if opts.ColorBg {
							ch = Ansi24Bg(cr, cg, cbl, ch)
						} else {
							ch = Ansi24(cr, cg, cbl, ch)
						}
					} else {
						code := RGBTo256(cr, cg, cbl)
						if opts.ColorBg {
							ch = Ansi8Bg(code, ch)
						} else {
							ch = Ansi8(code, ch)
						}
					}
				} else if opts.Grayscale {
					gr := Luminance(avgR, avgG, avgB)
					if opts.Negative {
						gr = 255 - gr
					}
					if opts.ColorMode == ColorTrue {
						if opts.ColorBg {
							ch = Ansi24Bg(gr, gr, gr, ch)
						} else {
							ch = Ansi24(gr, gr, gr, ch)
						}
					} else {
						code := GrayscaleTo256(gr)
						if opts.ColorBg {
							ch = Ansi8Bg(code, ch)
						} else {
							ch = Ansi8(code, ch)
						}
					}
				} else if opts.FontColorSet {
					cr, cg, cbl := opts.FontColor[0], opts.FontColor[1], opts.FontColor[2]
					if opts.ColorMode == ColorTrue {
						ch = Ansi24(cr, cg, cbl, ch)
					} else {
						code := RGBTo256(cr, cg, cbl)
						ch = Ansi8(code, ch)
					}
				}
			}
			sb.WriteString(ch)
		}
		result[cy] = sb.String()
	}
	return result
}
