// HelpText returns the --help output.
func HelpText() string {
	var sb strings.Builder
	sb.WriteString("This tool converts images into ascii art and prints them on the terminal.\n")
	sb.WriteString("Further configuration can be managed with flags.\n\n")
	sb.WriteString("Usage:\n")
	sb.WriteString("  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\n")
	sb.WriteString("Flags:\n")
	// Column widths
	for _, f := range flags {
		left := "  "
		if f.short != "" {
			left += "-" + f.short + ", "
		} else {
			left += "    "
		}
		left += "--" + f.long
		switch f.kind {
		case "int":
			left += " int"
		case "intlist":
			left += " ints"
		case "string":
			left += " string"
