	}
	if p.SaveGif != "" {
		fmt.Fprintln(os.Stderr, "Error: --save-gif is not supported in this build")
		return fmt.Errorf("save-gif unsupported")
	}

	return nil
}

func saveTxt(name, outDir string, rows []string) error {
	base := name
	if ext := filepath.Ext(base); ext != "" {
		base = base[:len(base)-len(ext)]
	}
