		return fmt.Errorf("save-gif unsupported")
	}

	return nil
}

func saveTxt(name, outDir string, rows []string) error {
	base := name
	if ext := filepath.Ext(base); ext != "" {
		base = base[:len(base)-len(ext)]
	}
	outPath := filepath.Join(outDir, base+"-ascii-art.txt")
	f, err := os.Create(outPath)
	if err != nil {
		return err
	}
	defer f.Close()
	// strip ANSI codes from rows when saving
	for _, r := range rows {
		fmt.Fprintln(f, stripAnsi(r))
	}
	return nil
}

func stripAnsi(s string) string {
	var sb strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			// skip until 'm'
			j := i + 2
			for j < len(s) && s[j] != 'm' {
				j++
			}
			if j < len(s) {
				i = j + 1
				continue
			}
		}
		sb.WriteByte(s[i])
		i++
	}
	return sb.String()
}
