package convert

import (
	"image"
	"image/color"
	"math"
)

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	px := math.Pi * x
	return math.Sin(px) / px
}

func lanczosKernel(x, radius float64) float64 {
	if x < 0 {
		x = -x
	}
	if x >= radius {
		return 0
	}
	return sinc(x) * sinc(x/radius)
}

type filterRow struct {
	start   int
	weights []float64
}

func makeFilter(srcSize, dstSize int, radius float64) []filterRow {
	rows := make([]filterRow, dstSize)
	scale := float64(srcSize) / float64(dstSize)
	support := radius
	if scale > 1 {
		support = radius * scale
	}
	for d := 0; d < dstSize; d++ {
		center := (float64(d)+0.5)*scale - 0.5
		start := int(math.Ceil(center - support))
		end := int(math.Floor(center + support))
		if start < 0 {
			start = 0
		}
		if end > srcSize-1 {
			end = srcSize - 1
		}
		weights := make([]float64, end-start+1)
		sum := 0.0
		for s := start; s <= end; s++ {
			x := (float64(s) - center)
			if scale > 1 {
				x /= scale
			}
			w := lanczosKernel(x, radius)
			weights[s-start] = w
			sum += w
		}
		if sum != 0 {
			for i := range weights {
				weights[i] /= sum
			}
		}
		rows[d] = filterRow{start: start, weights: weights}
	}
	return rows
}

func ResizeLanczos(src image.Image, dstW, dstH int) *image.RGBA {
	b := src.Bounds()
	srcW, srcH := b.Dx(), b.Dy()

	if dstW <= 0 || dstH <= 0 {
		return image.NewRGBA(image.Rect(0, 0, 0, 0))
	}

	srcRGBA := image.NewRGBA(image.Rect(0, 0, srcW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < srcW; x++ {
			c := src.At(b.Min.X+x, b.Min.Y+y)
			r, g, bc, a := c.RGBA()
			i := y*srcRGBA.Stride + x*4
			srcRGBA.Pix[i+0] = uint8(r >> 8)
			srcRGBA.Pix[i+1] = uint8(g >> 8)
			srcRGBA.Pix[i+2] = uint8(bc >> 8)
			srcRGBA.Pix[i+3] = uint8(a >> 8)
		}
	}

	const radius = 3.0
	filterX := makeFilter(srcW, dstW, radius)
	tmp := make([]float64, dstW*srcH*4)
	for y := 0; y < srcH; y++ {
		rowPix := srcRGBA.Pix[y*srcRGBA.Stride:]
		for x := 0; x < dstW; x++ {
			f := filterX[x]
			var r, g, bc, a float64
			for i, w := range f.weights {
				idx := (f.start + i) * 4
				r += float64(rowPix[idx+0]) * w
				g += float64(rowPix[idx+1]) * w
				bc += float64(rowPix[idx+2]) * w
				a += float64(rowPix[idx+3]) * w
			}
			ti := (y*dstW + x) * 4
			tmp[ti+0] = r
			tmp[ti+1] = g
			tmp[ti+2] = bc
			tmp[ti+3] = a
		}
	}

	filterY := makeFilter(srcH, dstH, radius)
	dst := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	for y := 0; y < dstH; y++ {
		f := filterY[y]
		for x := 0; x < dstW; x++ {
			var r, g, bc, a float64
			for i, w := range f.weights {
				ti := ((f.start+i)*dstW + x) * 4
				r += tmp[ti+0] * w
