cat > /workspace/internal/convert/resize.go <<'EOF'
package convert

import (
	"image"
	"image/color"
	"math"
)

// sinc returns sin(pi*x) / (pi*x), with sinc(0)=1.
func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	px := math.Pi * x
	return math.Sin(px) / px
}

// lanczos3Kernel matches nfnt/resize's Lanczos3 kernel.
func lanczos3Kernel(x float64) float64 {
	if x < -3 || x > 3 {
		return 0
	}
	return sinc(x) * sinc(x/3)
}

// filterEntry is a precomputed weight contribution.
type filterEntry struct {
	idx    int
	weight int32
}

// makeWeights builds a list of (idx,weight) entries per output sample.
// Weights are 16.16 fixed point integers whose per-row sum is 65536.
func makeWeights(srcSize, dstSize int, kernel func(float64) float64, radius float64) [][]filterEntry {
	scale := float64(srcSize) / float64(dstSize)
	support := radius
	if scale > 1 {
		support = radius * scale
	}
	res := make([][]filterEntry, dstSize)
	for v := 0; v < dstSize; v++ {
		center := (float64(v)+0.5)*scale - 0.5
		start := int(math.Ceil(center - support))
		end := int(math.Floor(center + support))
		if start < 0 {
			start = 0
		}
		if end > srcSize-1 {
			end = srcSize - 1
		}
		floatW := make([]float64, end-start+1)
		sum := 0.0
		for i := start; i <= end; i++ {
			x := float64(i) - center
			if scale > 1 {
				x /= scale
			}
			w := kernel(x)
			floatW[i-start] = w
			sum += w
		}
		// normalize and convert to fixed-point int
		entries := make([]filterEntry, 0, end-start+1)
		if sum != 0 {
			for i := range floatW {
				floatW[i] /= sum
			}
		}
		// Convert to fixed-point, preserving sum.
		runningSum := int32(0)
		for i := start; i <= end; i++ {
			w := int32(math.Round(floatW[i-start] * 65536))
			if w != 0 {
				entries = append(entries, filterEntry{idx: i, weight: w})
				runningSum += w
			}
		}
		// Correct rounding error.
		if len(entries) > 0 {
			diff := int32(65536) - runningSum
			// distribute to the largest entry
			maxI := 0
			for i := range entries {
				if entries[i].weight > entries[maxI].weight {
					maxI = i
				}
			}
			entries[maxI].weight += diff
		}
		res[v] = entries
	}
	return res
}

// ResizeLanczos resizes src to dstW x dstH using Lanczos-3 interpolation.
func ResizeLanczos(src image.Image, dstW, dstH int) *image.RGBA {
	b := src.Bounds()
	srcW, srcH := b.Dx(), b.Dy()

	if dstW <= 0 || dstH <= 0 {
		return image.NewRGBA(image.Rect(0, 0, 0, 0))
	}

	// Convert src to RGBA buffer (stride = srcW*4).
	srcRGBA := image.NewRGBA(image.Rect(0, 0, srcW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < srcW; x++ {
			c := src.At(b.Min.X+x, b.Min.Y+y)
			r, g, bc, a := c.RGBA()
			i := y*srcRGBA.Stride + x*4
			srcRGBA.Pix[i+0] = uint8(r >> 8)
			srcRGBA.Pix[i+1] = uint8(g >> 8)
			srcRGBA.Pix[i+2] = uint8(bc >> 8)
			srcRGBA.Pix[i+3] = uint8(a >> 8)
		}
	}

	const radius = 3.0
	// horizontal pass srcW -> dstW, same srcH
	xw := makeWeights(srcW, dstW, lanczos3Kernel, radius)
	tmp := make([]int32, dstW*srcH*4)
	for y := 0; y < srcH; y++ {
		rowPix := srcRGBA.Pix[y*srcRGBA.Stride:]
		for x := 0; x < dstW; x++ {
			var r, g, bc, a int64
			for _, e := range xw[x] {
				idx := e.idx * 4
				w := int64(e.weight)
				r += int64(rowPix[idx+0]) * w
				g += int64(rowPix[idx+1]) * w
				bc += int64(rowPix[idx+2]) * w
				a += int64(rowPix[idx+3]) * w
			}
			ti := (y*dstW + x) * 4
			tmp[ti+0] = int32(r >> 16)
			tmp[ti+1] = int32(g >> 16)
			tmp[ti+2] = int32(bc >> 16)
			tmp[ti+3] = int32(a >> 16)
		}
	}

	// vertical pass srcH -> dstH
	yw := makeWeights(srcH, dstH, lanczos3Kernel, radius)
	dst := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			var r, g, bc, a int64
			for _, e := range yw[y] {
				ti := (e.idx*dstW + x) * 4
				w := int64(e.weight)
				r += int64(tmp[ti+0]) * w
				g += int64(tmp[ti+1]) * w
				bc += int64(tmp[ti+2]) * w
				a += int64(tmp[ti+3]) * w
			}
			dst.SetRGBA(x, y, color.RGBA{
				clampI(r >> 16),
				clampI(g >> 16),
				clampI(bc >> 16),
				clampI(a >> 16),
			})
		}
	}
	return dst
}

func clampI(v int64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}
EOF
