	dotBits := [4][2]int{
		{1, 8},
		{2, 16},
		{4, 32},
		{64, 128},
	}
	b := img.Bounds()
	iw, ih := b.Dx(), b.Dy()
	lum := make([]float64, iw*ih)
	for y := 0; y < ih; y++ {
		for x := 0; x < iw; x++ {
			i := y*img.Stride + x*4
			lum[y*iw+x] = float64(Luminance(img.Pix[i], img.Pix[i+1], img.Pix[i+2]))
		}
	}
	on := make([]bool, iw*ih)
	if dither {
		for y := 0; y < ih; y++ {
			for x := 0; x < iw; x++ {
				old := lum[y*iw+x]
				var newv float64
				if old >= 128 {
					newv = 255
					on[y*iw+x] = true
				} else {
					newv = 0
				}
				err := old - newv
				if x+1 < iw {
					lum[y*iw+x+1] += err * 7 / 16
