package convert

import (
	"image"
	"image/color"
	"math"
)

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	px := math.Pi * x
	return math.Sin(px) / px
}

func lanczos3Kernel(x float64) float64 {
	if x < -3 || x > 3 {
		return 0
	}
	return sinc(x) * sinc(x/3)
}

type filterEntry struct {
	idx    int
	weight float64
}

func makeWeights(srcSize, dstSize int, kernel func(float64) float64, radius float64) [][]filterEntry {
	scale := float64(srcSize) / float64(dstSize)
	support := radius
	if scale > 1 {
		support = radius * scale
	}
	res := make([][]filterEntry, dstSize)
	for v := 0; v < dstSize; v++ {
		center := (float64(v)+0.5)*scale - 0.5
		start := int(math.Ceil(center - support))
		end := int(math.Floor(center + support))
		if start < 0 {
			start = 0
		}
		if end > srcSize-1 {
			end = srcSize - 1
		}
		floatW := make([]float64, end-start+1)
		sum := 0.0
		for i := start; i <= end; i++ {
			x := float64(i) - center
			if scale > 1 {
				x /= scale
			}
			w := kernel(x)
			floatW[i-start] = w
			sum += w
		}
		entries := make([]filterEntry, 0, end-start+1)
		if sum != 0 {
			for i := range floatW {
				floatW[i] /= sum
			}
		}
		for i := start; i <= end; i++ {
			w := floatW[i-start]
			entries = append(entries, filterEntry{idx: i, weight: w})
		}
		res[v] = entries
	}
	return res
}

func ResizeLanczos(src image.Image, dstW, dstH int) *image.RGBA {
	b := src.Bounds()
	srcW, srcH := b.Dx(), b.Dy()

	if dstW <= 0 || dstH <= 0 {
		return image.NewRGBA(image.Rect(0, 0, 0, 0))
	}

	srcRGBA := image.NewRGBA(image.Rect(0, 0, srcW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < srcW; x++ {
			c := src.At(b.Min.X+x, b.Min.Y+y)
			r, g, bc, a := c.RGBA()
			i := y*srcRGBA.Stride + x*4
			srcRGBA.Pix[i+0] = uint8(r >> 8)
			srcRGBA.Pix[i+1] = uint8(g >> 8)
			srcRGBA.Pix[i+2] = uint8(bc >> 8)
			srcRGBA.Pix[i+3] = uint8(a >> 8)
		}
	}

	const radius = 3.0
	xw := makeWeights(srcW, dstW, lanczos3Kernel, radius)
	tmp := make([]float64, dstW*srcH*4)
	for y := 0; y < srcH; y++ {
		rowPix := srcRGBA.Pix[y*srcRGBA.Stride:]
		for x := 0; x < dstW; x++ {
			var r, g, bc, a float64
			for _, e := range xw[x] {
				idx := e.idx * 4
				r += float64(rowPix[idx+0]) * e.weight
				g += float64(rowPix[idx+1]) * e.weight
				bc += float64(rowPix[idx+2]) * e.weight
				a += float64(rowPix[idx+3]) * e.weight
			}
			ti := (y*dstW + x) * 4
			tmp[ti+0] = r
			tmp[ti+1] = g
			tmp[ti+2] = bc
			tmp[ti+3] = a
		}
	}

	yw := makeWeights(srcH, dstH, lanczos3Kernel, radius)
	dst := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			var r, g, bc, a float64
			for _, e := range yw[y] {
				ti := (e.idx*dstW + x) * 4
				r += tmp[ti+0] * e.weight
				g += tmp[ti+1] * e.weight
				bc += tmp[ti+2] * e.weight
				a += tmp[ti+3] * e.weight
			}
			dst.SetRGBA(x, y, color.RGBA{
				clamp8(r), clamp8(g), clamp8(bc), clamp8(a),
			})
		}
	}
	return dst
}

func clamp8(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v + 0.5)
}
