package convert

import (
	"fmt"
	"os"
	"strings"
)

type ColorMode int

const (
	ColorNone ColorMode = iota
	Color256
	ColorTrue
)

func DetectColorMode() ColorMode {
	term := os.Getenv("TERM")
	colorterm := strings.ToLower(os.Getenv("COLORTERM"))
	if term == "" || term == "dumb" {
		return ColorNone
	}
	if colorterm == "truecolor" || colorterm == "24bit" {
		return ColorTrue
	}
	if strings.Contains(term, "direct") || strings.Contains(term, "truecolor") {
		return ColorTrue
	}
	if strings.Contains(term, "xterm") || strings.Contains(term, "screen") || strings.Contains(term, "vt100") || strings.Contains(term, "tmux") || strings.Contains(term, "linux") || strings.Contains(term, "rxvt") || strings.Contains(term, "ansi") || strings.Contains(term, "cygwin") || strings.Contains(term, "konsole") || strings.Contains(term, "256") {
		return Color256
	}
	return ColorNone
}

func Ansi24(r, g, b uint8, s string) string {
	return fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", r, g, b, s)
}
func Ansi24Bg(r, g, b uint8, s string) string {
	return fmt.Sprintf("\x1b[48;2;%d;%d;%dm%s\x1b[0m", r, g, b, s)
}
func Ansi8(code int, s string) string {
	return fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", code, s)
}
func Ansi8Bg(code int, s string) string {
	return fmt.Sprintf("\x1b[48;5;%dm%s\x1b[0m", code, s)
}

func RGBTo256(r, g, b uint8) int {
	levels := [6]int{0, 95, 135, 175, 215, 255}
	cubeIdx := func(v uint8) int {
		best := 0
		bestD := 1000
		vv := int(v)
		for i, l := range levels {
			d := vv - l
			if d < 0 {
				d = -d
			}
			if d < bestD {
				bestD = d
				best = i
			}
		}
		return best
	}
	ri := cubeIdx(r)
	gi := cubeIdx(g)
	bi := cubeIdx(b)
	if ri == gi && gi == bi {
		if ri == 0 {
			return 0
		}
		if ri == 5 {
			return 15
		}
	}
	return 16 + 36*ri + 6*gi + bi
}
func GrayscaleTo256(v uint8) int { return RGBTo256(v, v, v) }
