				r += float64(tmp.Pix[ti+0]) * e.weight
				g += float64(tmp.Pix[ti+1]) * e.weight
				bc += float64(tmp.Pix[ti+2]) * e.weight
				a += float64(tmp.Pix[ti+3]) * e.weight
			}
			di := y*dst.Stride + x*4
			dst.Pix[di+0] = clamp8(r)
			dst.Pix[di+1] = clamp8(g)
			dst.Pix[di+2] = clamp8(bc)
			dst.Pix[di+3] = clamp8(a)
		}
	}
