package term

import (
	"os"
	"syscall"
	"unsafe"
)

// GetSize returns the terminal (cols, rows) or (0, 0) on failure.
// Tries stdout, stderr, stdin, and finally /dev/tty.
func GetSize() (int, int) {
	for _, f := range []*os.File{os.Stdout, os.Stderr, os.Stdin} {
		if w, h, ok := ioctlSize(f); ok {
			return w, h
		}
	}
	// fall back to /dev/tty
	if tty, err := os.Open("/dev/tty"); err == nil {
		defer tty.Close()
		if w, h, ok := ioctlSize(tty); ok {
			return w, h
		}
	}
	return 0, 0
}

func ioctlSize(f *os.File) (int, int, bool) {
	type winsize struct {
		Row, Col       uint16
		Xpixel, Ypixel uint16
	}
	ws := &winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		f.Fd(),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	if errno != 0 {
		return 0, 0, false
	}
	return int(ws.Col), int(ws.Row), true
}

func IsTerminal(f *os.File) bool {
	_, _, ok := ioctlSize(f)
	return ok
}
EOF
