package convert

import (
	"bytes"
	"image"
	"image/color"
	"image/gif"
	"image/png"
	"io"
)

// Basic monospaced 8x16 bitmap font: each glyph is 16 bytes (one per row).
// This font is derived from a simple built-in character set.
// Only printable ASCII is included; other characters render as space.
// Note: the binary output won't be byte-identical to the original tool,
// but it will be a valid PNG of sensible shape.

// defaultCharW and defaultCharH are the pixel dimensions of a glyph.
const (
	defaultCharW = 8
	defaultCharH = 16
)

// SavePng writes a PNG of the ASCII grid. rows contains the ASCII strings
// (ANSI escapes optional; they're ignored for layout).  bg is the background
// RGBA, fg the foreground.
func SavePng(w io.Writer, rows []string, fg color.RGBA, bg color.RGBA) error {
	img := renderGrid(rows, fg, bg)
	return png.Encode(w, img)
}

// SaveGif writes a GIF with one frame per input grid.
func SaveGif(w io.Writer, frames [][]string, delays []int, fg color.RGBA, bg color.RGBA) error {
	palette := color.Palette{bg, fg}
	g := &gif.GIF{LoopCount: 0}
	for i, rows := range frames {
		img := renderGrid(rows, fg, bg)
		pimg := image.NewPaletted(img.Bounds(), palette)
		for y := 0; y < img.Bounds().Dy(); y++ {
			for x := 0; x < img.Bounds().Dx(); x++ {
				pimg.Set(x, y, img.At(x, y))
			}
		}
		g.Image = append(g.Image, pimg)
		d := 10
		if i < len(delays) {
			d = delays[i]
		}
		g.Delay = append(g.Delay, d)
	}
	var buf bytes.Buffer
	if err := gif.EncodeAll(&buf, g); err != nil {
		return err
	}
	_, err := w.Write(buf.Bytes())
	return err
}

func renderGrid(rows []string, fg, bg color.RGBA) *image.RGBA {
	// width = max stripped row length * defaultCharW; height = #rows * defaultCharH
	maxW := 0
	stripped := make([]string, len(rows))
	for i, r := range rows {
		s := stripAnsi(r)
		stripped[i] = s
		if len(s) > maxW {
			maxW = len(s)
		}
	}
	iw := maxW * defaultCharW
	ih := len(rows) * defaultCharH
	if iw < 1 {
		iw = 1
	}
	if ih < 1 {
		ih = 1
	}
	img := image.NewRGBA(image.Rect(0, 0, iw, ih))
	// Fill bg.
	for y := 0; y < ih; y++ {
		for x := 0; x < iw; x++ {
			img.SetRGBA(x, y, bg)
		}
	}
	// Draw characters.
	for ri, row := range stripped {
		for ci, ch := range row {
			drawGlyph(img, ci*defaultCharW, ri*defaultCharH, rune(ch), fg)
		}
	}
	return img
}

func drawGlyph(img *image.RGBA, x, y int, ch rune, fg color.RGBA) {
	g := getGlyph(ch)
	for dy := 0; dy < defaultCharH; dy++ {
		row := g[dy]
		for dx := 0; dx < defaultCharW; dx++ {
			if (row>>(7-dx))&1 != 0 {
				px := x + dx
				py := y + dy
				if px >= 0 && py >= 0 && px < img.Bounds().Dx() && py < img.Bounds().Dy() {
					img.SetRGBA(px, py, fg)
				}
			}
		}
	}
}

func stripAnsi(s string) string {
	var b []byte
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			j := i + 2
			for j < len(s) && s[j] != 'm' {
				j++
			}
			if j < len(s) {
				i = j + 1
				continue
			}
		}
		b = append(b, s[i])
		i++
	}
	return string(b)
}

// getGlyph returns a 16-row bitmap for the given rune.
// Uses a fallback rectangle for unsupported runes.
func getGlyph(r rune) [defaultCharH]byte {
	if g, ok := glyphs[r]; ok {
		return g
	}
	var fallback [defaultCharH]byte
	return fallback
